const students = [{ id: 1, name: "小雨" }, { id: 2, name: "小林" }];
const courses = [{ id: 10, title: "数据库入门" }, { id: 20, title: "JavaScript" }];
const enrollments = [{ studentId: 1, courseId: 10 }, { studentId: 2, courseId: 20 }];

// 每一条 enrollment 是一次关系，先拿到两个编号。
const result = enrollments.map((enrollment) => {
  // student_id 连接 students.id。
  const student = students.find((item) => item.id === enrollment.studentId);
  // course_id 连接 courses.id。
  const course = courses.find((item) => item.id === enrollment.courseId);
  // 把两张表中真正想展示的列组合成一行结果。
  return { student: student.name, course: course.title };
});

console.log("报名结果:", result);
